class Solution {
  public int areaOfMaxDiagonal(int[][] d) {
    long best = -1;
    int ans = 0;
    for (int[] x : d) {
      long q = (long) x[0] * x[0] + (long) x[1] * x[1];
      int ar = x[0] * x[1];
      if (q > best || q == best && ar > ans) {
        best = q;
        ans = ar;
      }
    }
    return ans;
  }
}
